<script setup lang="ts">
import { ref } from 'vue'; import { useRouter } from 'vue-router'; import BaseButton from '../../components/ui/BaseButton.vue'; import { useCompanyOnboardingStore } from '../../stores/companyOnboarding'
const router = useRouter(); const store = useCompanyOnboardingStore(); const error = ref('')
async function submit() { if (!store.state.termsAccepted) { error.value = 'Aceite os termos para continuar.'; return }; try { await store.submit(); router.push('/cadastro/concluido') } catch { error.value = store.submitError } }
</script>
<template><section><h1 class="text-3xl font-medium tracking-tight sm:text-4xl">Última etapa!</h1><p class="mt-5 leading-7 text-neutral-600">Leia os termos para criar seu espaço de trabalho.</p><div class="mt-8 max-h-[400px] overflow-y-auto rounded-xl border border-neutral-200 p-5 text-sm leading-6 text-neutral-600"><p>Ao criar sua empresa, você confirma que os dados informados são verdadeiros e autoriza o tratamento necessário para provisionar a organização, sua associação como proprietário e os recursos do plano selecionado.</p><p class="mt-4">Os termos completos, a versão aceita e a política de privacidade serão registrados pelo backend no momento da criação.</p></div><label class="mt-6 flex items-start gap-3 text-sm leading-6"><input v-model="store.state.termsAccepted" type="checkbox" class="mt-1 h-4 w-4 accent-lime-500" />Li e concordo com os Termos de Uso e Política de Privacidade</label><p v-if="error" class="mt-3 text-sm text-red-600">{{ error }}</p><BaseButton class="mt-8 min-h-[56px] w-full text-base sm:min-h-[68px] sm:text-lg" :disabled="store.submitting" @click="submit">{{ store.submitting ? 'Preparando sua empresa...' : 'Aceitar e criar minha empresa' }}</BaseButton></section></template>
